utp_relevant_fg BIGNUMERIC(38,0) OPTIONS(description='Gibt an ob einen Artikel als UTP-relevant markiert ist (0 oder 1).UTP = Unfair trade practices. Ist ein EU-Gesetz um kleine Lieferanten vor Großaufträgen zu schützen.'),
utp_relevant_aenderung_fg BIGNUMERIC(38,0) OPTIONS(description='Flag zeigt die Änderung der UTP_RELEVANT_FG im Vergleich zum Vortag (1 oder 0). Ist für den User hilfreich um nach Änderungen zu filtern.'),
utp_lieferant_bestaetigt_fg BIGNUMERIC(38,0) OPTIONS(description='Flag gibt an, ob ein UTP-Lieferant die Werbebestellmenge freigegeben hat (0 oder 1).'),
dat_gueltig_von_konditionsart_zar5 DATE OPTIONS(description='Beginn der Gültigkeit der Konditionsart ZAR5.'),
dat_gueltig_bis_konditionsart_zar5 DATE OPTIONS(description='Ende der Gültigkeit der Konditionsart ZAR5.'),
menge_kolliinhalt_vortag_bme BIGNUMERIC(38,3) OPTIONS(description='Kolliinhalt des Vortages. Aus Feld: Kollifaktor (Menge in BME pro Kolli).'),
init_lief_modus_kz STRING(100) OPTIONS(description='Beschreibt den Modus, in welchem die initiale Belieferung berechnet wird (O = Order, S = Simulation, N = None).- N: wenn keine initiale Belieferung errechnet wird (vor wbs_phase_id = 8).- S: berechnen die Erstlieferung 40 Tage vor der Promotion - es werden keine wirklichen Bestellungen in den Geschäften erzeugt sondern die Spalte ermöglicht DC Dispo, den ersten Liefersplit schon sehr früh zu sehen und die Mengen beim Lieferanten entsprechend zu bestellen (wbs_phase_id 7 bis 3).- O: der ursprüngliche initiale Lieferlauf findet 9 Tage vor der Promotion statt, und der Berechnungslauf wird als "O" (Order Creation) gekennzeichnet (ab wbs_phase_id = 2).'),
gp_id_aenderung_fg BIGNUMERIC(38,0) OPTIONS(description='Flag, welches angibt, ob sich die Lieferantennummer (GP_ID) geändert hat'),
konditionsart_zar5_gueltigkeit_aenderung_fg BIGNUMERIC(38,0) OPTIONS(description='Flag, welches angibt, ob sich der Zeitraum für die ZAR5-Gültigkeit geändert hat.'),
posten_kz_sap STRING(2) COLLATE 'und:ci' OPTIONS(description='Postenkennzeichen. Für Artikel, die nicht ständig im Sortiment sind (Unterschied zur posten_id: für KMO werden die tatsächlichen Werte aus SAP gespeichert)'),
posten_kz_sap_aenderung_fg BIGNUMERIC(38,0) OPTIONS(description='Flag, welches angibt, ob der Artikel von Posten auf Sortimentsartikel oder umgekehrt geändert hat'),
bonuskauf_promotionstyp_liste_txt STRING(1000) OPTIONS(description='Die Spalte enthält den konkatenierte Aktionsart (Feld AKART in PMR), erwartete Einträge sind z.B. 0001, 0005, ZAI, ZBBR.Gibt die Aktionsart für eine Aktion_ID an Z.B:Aktionsart\'0001\' eine Standard-Aktion im Prospektoder\'ZBBR\' wäre eine Bonuskauf-Aktion.Die Art der Aktion hat Einfluss darauf, ob und wie die SCM-Mengen für diese Aktion berechnet werden.'),
saison_id STRING(10) COLLATE 'und:ci' OPTIONS(description='ID der Saison aus saiso, z.Bsp 9.'),
saison_id_aenderung_fg BIGNUMERIC(38,0) OPTIONS(description='Flag, gibt an, ob der Artikel das Saisonkennzeichen geändert hat'),
best_menge_einh_id STRING(3) COLLATE 'und:ci' OPTIONS(description='Bestellmengeneinheit. Diese Mengeneinheit wird standardmäßig bei Bestellungen verwendet.'),
best_menge_einh_vortag_id STRING(3) OPTIONS(description='Bestellmengeneinheit des Vortages. Diese Mengeneinheit wird standardmäßig bei Bestellungen verwendet.'),
best_menge_einh_id_aenderung_fg BIGNUMERIC(38,0) OPTIONS(description='Flag, gibt an, ob es eine Änderung der Bestellmengeneinheit zum Vortag gab'),
bedarf_estimation_id_2_bme NUMERIC(18,3) OPTIONS(description='Simulierter Bedarf in Basismengeneinheit, welcher unter Verwendung der Estimation_ID = 2 ermittelt werden würde.'),
bestellmenge_estimation_id_2_ohne_bestand_ame BIGNUMERIC(38,3) OPTIONS(description='Simulierte Werbe-Bestellmenge ohne Bestandsberücksichtigung in Ausliefermengeneinheit (AME, z.B. Kolli oder KG), welcher unter Verwendung der Estimation_ID = 2 ermittelt werden würde.'),
bestellmenge_estimation_id_2_mit_bestand_ame BIGNUMERIC(38,3) OPTIONS(description='Simulierte Werbe-Bestellmenge mit Bestandsberücksichtigung in Ausliefermengeneinheit (AME, z.B. Kolli oder KG), welcher unter Verwendung der Estimation_ID = 2 ermittelt werden würde.'),
adjustment_id BIGNUMERIC(38,0) OPTIONS(description='Mit der Adjustment_ID kann der Benutzer entscheiden, auf welche Weise die Nachversorgung in WBS TP1 berechnet werden soll.0 = UDF&R: UDF berechnet die Prognosen und übergibt sie an F&R1 = Standard adjustment (WBS): WBS berechnet die Nachversorgungsmenge und stellt sie den Benutzern als PREX-Upload zur Verfügung.2 = Platzhalter (Stand 28.03.2025)3 = External adjustment: Die SAP Autodispo errechnet keine Mengen. In diesem Fall ist eine manuelle Bestellanlage durch das Land notwendig.'),
td_update TIMESTAMP OPTIONS(description='Technical fields for synchronisation framework. Will be delted after last product migration'),
td_insert TIMESTAMP OPTIONS(description='Technical fields for synchronisation framework. Will be delted after last product migration'),
PRIMARY KEY (mandant_id, offer_id, wup_id, art_id, dat_beladung, mandant_id_vz, wup_id_vz) NOT ENFORCED
) OPTIONS(description='SCM-WBS - Werbeänderungen (kumuliert).');
